\title{Finite-Horizon Shadowing Certificates for Numerical Dynamics,\\Logistic Iteration, and Residual Systems}
\author{Aristotle}
\date{July 18, 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop a quantitative theory comparing a finite pseudo-orbit with an exact orbit of a Lipschitz dynamical system. If a sequence has one-step defect at most $\delta$ under an $L$-Lipschitz map, the exact orbit beginning at the same initial point remains within $\delta\sum_{k=0}^{n-1}L^k$ at time $n$. This yields a horizon-independent radius $\delta/(1-L)$ for contractions. For the parameter-four logistic map $f(x)=4x(1-x)$, invariance of $[0,1]$ and a Lipschitz constant of four give the closed certificate $\delta(4^n-1)/3$ and the sufficient precision condition $\delta(4^N-1)\leq3\varepsilon$. Residual dynamics $z\mapsto z+g(z)$ inherit the same calculus with amplification factor $1+L$ when $g$ is $L$-Lipschitz. Algorithms for defect auditing and precision planning are presented, and the limits of scalar Lipschitz analysis for chaotic shadowing are made explicit.
\end{abstract}

\section{Introduction}
Numerical dynamics replaces exact iteration by approximate updates. Finite precision, approximate function evaluation, quantization, and communication noise introduce fresh discrepancies at every step. In a stable system these defects may decay; in an expanding system they may be amplified. A rigorous interpretation therefore separates two questions: how large is the local defect produced by the computation, and how does the mathematical map propagate it?

A floating-point format alone does not specify a local error bound; intermediate magnitudes, operation order, overflow, underflow, and exceptional values matter. Conversely, a local certificate does not guarantee long-time accuracy. This paper gives the baseline consequence of a one-step defect bound and Lipschitz continuity. The resulting finite-horizon shadow starts at the reported initial state and has a geometric error budget.

For the logistic map at parameter four, the budget grows like $4^n$. It converts tolerance and horizon into a sufficient local precision, but also shows why ordinary continuity cannot support a million-step accuracy claim. For residual learning systems, the same recurrence treats network depth as discrete time. Thus dynamical simulation and depth-wise perturbation propagation share one error calculus.

\section{Definitions and local propagation}
Let $E$ be a normed real vector space and $f:E\to E$.

\begin{definition}[Exact orbit]
Given $y_0\in E$, the exact orbit is $y_n=f^n(y_0)$, equivalently $y_{n+1}=f(y_n)$.
\end{definition}

\begin{definition}[Finite pseudo-orbit]
For $\delta\geq0$ and $N\in\mathbb N$, a sequence $x_0,\ldots,x_N$ is a $\delta$-pseudo-orbit through horizon $N$ if
\[
 \lVert x_{n+1}-f(x_n)\rVert\leq\delta\qquad(0\leq n<N).
\]
Its local defect at step $n$ is $d_n=\lVert x_{n+1}-f(x_n)\rVert$.
\end{definition}

\begin{definition}[Lipschitz dynamics]
The map $f$ is $L$-Lipschitz if $L\geq0$ and
\[
 \lVert f(a)-f(b)\rVert\leq L\lVert a-b\rVert
\]
for all $a,b\in E$.
\end{definition}

\begin{definition}[Same-initial-condition shadow]
The canonical exact comparison orbit for $(x_n)$ is $y_n=f^n(x_0)$. A horizon $N$ is certified at tolerance $\varepsilon$ if $\lVert x_n-y_n\rVert\leq\varepsilon$ for every $0\leq n\leq N$.
\end{definition}

\begin{lemma}[One-step error propagation]
If $f$ is $L$-Lipschitz, $(x_n)$ is a $\delta$-pseudo-orbit, and $y_{n+1}=f(y_n)$, then
\[
 \lVert x_{n+1}-y_{n+1}\rVert
 \leq\delta+L\lVert x_n-y_n\rVert
\]
for every certified step.
\end{lemma}
\begin{proof}
Insert and subtract $f(x_n)$:
\[
 x_{n+1}-f(y_n)=\bigl(x_{n+1}-f(x_n)\bigr)
 +\bigl(f(x_n)-f(y_n)\bigr).
\]
The triangle inequality, the defect bound, and Lipschitz continuity give the result.
\end{proof}

For variable defects and $e_n=\lVert x_n-y_n\rVert$, the same argument yields
\[
 e_n\leq L^ne_0+\sum_{j=0}^{n-1}L^{n-1-j}d_j.
\]
This weighted convolution is useful when individual rounding certificates are available.

\section{Finite-horizon shadowing}
\begin{theorem}[Finite-Horizon Shadowing Theorem]
Let $f:E\to E$ be $L$-Lipschitz with $L\geq0$. If $x_0,\ldots,x_N$ is a $\delta$-pseudo-orbit with $\delta\geq0$, then the exact orbit $y_n=f^n(x_0)$ satisfies
\[
 \lVert x_n-y_n\rVert\leq\delta\sum_{k=0}^{n-1}L^k
\]
for every $0\leq n\leq N$, with the sum at $n=0$ interpreted as zero.
\end{theorem}
\begin{proof}
Set $e_n=\lVert x_n-y_n\rVert$. Since $y_0=x_0$, $e_0=0$. If the claimed estimate holds at $n$, the preceding lemma gives
\[
 e_{n+1}\leq\delta+Le_n
 \leq\delta+L\delta\sum_{k=0}^{n-1}L^k
 =\delta\sum_{k=0}^{n}L^k.
\]
Induction proves the theorem.
\end{proof}

For $L\neq1$, the sum equals $(L^n-1)/(L-1)$; for $L=1$, it equals $n$. Consequently,
\[
 e_n\leq
 \begin{cases}
 \delta(1-L^n)/(1-L),&0\leq L<1,\\
 n\delta,&L=1,\\
 \delta(L^n-1)/(L-1),&L>1.
 \end{cases}
\]

\begin{theorem}[Uniform Contraction Shadowing Theorem]
Under the preceding assumptions, if $0\leq L<1$, then
\[
 \lVert x_n-f^n(x_0)\rVert\leq\frac{\delta}{1-L}
\]
for every $0\leq n\leq N$, independently of the horizon.
\end{theorem}
\begin{proof}
The nonnegative geometric sum satisfies
\[
 \sum_{k=0}^{n-1}L^k=\frac{1-L^n}{1-L}\leq\frac1{1-L}.
\]
Apply the finite-horizon theorem.
\end{proof}

\begin{remark}[Scope]
When $L>1$, the estimate grows geometrically. It need not describe the typical error of a concrete orbit, but the hypotheses alone permit that amplification. Classical hyperbolic shadowing uses stable and unstable directions and may adjust the initial point. A scalar Lipschitz constant contains no such directional information, so the theorem is not an infinite-time shadowing result.
\end{remark}

\section{The parameter-four logistic map}
Define $f:\mathbb R\to\mathbb R$ by
\[
 f(x)=4x(1-x).
\]

\begin{lemma}[Forward invariance]
If $x\in[0,1]$, then $f(x)\in[0,1]$.
\end{lemma}
\begin{proof}
Both factors in $4x(1-x)$ are nonnegative. Moreover,
\[
 f(x)=1-4\left(x-\frac12\right)^2\leq1.
\]
\end{proof}

\begin{corollary}[Invariant exact orbit]
If $y_0\in[0,1]$ and $y_{n+1}=f(y_n)$, then $y_n\in[0,1]$ for every $n\geq0$.
\end{corollary}
\begin{proof}
Apply forward invariance inductively.
\end{proof}

\begin{lemma}[Interval Lipschitz estimate]
For $x,y\in[0,1]$,
\[
 |f(x)-f(y)|\leq4|x-y|.
\]
\end{lemma}
\begin{proof}
Factoring gives $f(x)-f(y)=4(x-y)(1-x-y)$. Since $x+y\in[0,2]$, one has $|1-x-y|\leq1$.
\end{proof}

The constant four is sharp globally on the interval, since $f'(x)=4-8x$ has magnitude approaching four at either endpoint.

\begin{theorem}[Logistic Finite-Horizon Shadowing Theorem]
Let $x_0,\ldots,x_N\in[0,1]$, let $\delta\geq0$, and suppose
\[
 |x_{n+1}-4x_n(1-x_n)|\leq\delta\qquad(0\leq n<N).
\]
If $y_0=x_0$ and $y_{n+1}=4y_n(1-y_n)$, then
\[
 |x_n-y_n|\leq\delta\sum_{k=0}^{n-1}4^k
\]
for every $0\leq n\leq N$.
\end{theorem}
\begin{proof}
The exact orbit remains in $[0,1]$ by invariance, while the reported points lie there by assumption. Apply the interval Lipschitz estimate and the general theorem with $L=4$.
\end{proof}

\begin{corollary}[Closed logistic budget]
Under the same hypotheses,
\[
 |x_n-y_n|\leq\delta\frac{4^n-1}{3}.
\]
\end{corollary}
\begin{proof}
Use $\sum_{k=0}^{n-1}4^k=(4^n-1)/3$.
\end{proof}

\begin{theorem}[Logistic Precision Certificate]
Let $\varepsilon\geq0$. Under the logistic theorem's hypotheses, if
\[
 \delta(4^N-1)\leq3\varepsilon,
\]
then $|x_n-y_n|\leq\varepsilon$ for every $0\leq n\leq N$.
\end{theorem}
\begin{proof}
For $n\leq N$, monotonicity gives $4^n\leq4^N$. Apply the closed budget and the assumed inequality.
\end{proof}

Thus a sufficient local requirement is
\[
 \delta\leq\frac{3\varepsilon}{4^N-1}.
\]
For fixed $\delta>0$, the largest globally certified horizon is
\[
 N_{\max}=\left\lfloor\log_4\left(1+\frac{3\varepsilon}{\delta}\right)\right\rfloor,
\]
with the final integer decision best checked directly to avoid logarithmic rounding at a boundary.

For $\delta=10^{-16}$ and $\varepsilon=10^{-10}$, the condition is $4^N-1\leq3\times10^6$. Since $4^{10}=1{,}048{,}576$ and $4^{11}=4{,}194{,}304$, the certificate accepts $N=10$ and rejects $N=11$. A million-step guarantee is therefore unavailable from this global factor-four analysis. Nor is ordinary binary search for a nearby initial state justified: long-itinerary discrepancy is not generally monotone in the initial value.

\section{Residual systems}
Let $g:E\to E$ and define $F(z)=z+g(z)$.

\begin{lemma}[Residual block estimate]
If $g$ is $L$-Lipschitz with $L\geq0$, then $F$ is $(1+L)$-Lipschitz.
\end{lemma}
\begin{proof}
For all $a,b\in E$,
\[
 \begin{aligned}
 \lVert F(a)-F(b)\rVert
 &\leq\lVert a-b\rVert+\lVert g(a)-g(b)\rVert\\
 &\leq(1+L)\lVert a-b\rVert.
 \end{aligned}
\]
\end{proof}

\begin{theorem}[Residual-System Finite-Horizon Shadowing Theorem]
Suppose $g$ is $L$-Lipschitz and
\[
 \lVert x_{n+1}-(x_n+g(x_n))\rVert\leq\delta
\]
for $0\leq n<N$. If $y_0=x_0$ and $y_{n+1}=y_n+g(y_n)$, then
\[
 \lVert x_n-y_n\rVert
 \leq\delta\sum_{k=0}^{n-1}(1+L)^k
\]
for every $0\leq n\leq N$.
\end{theorem}
\begin{proof}
Apply the general finite-horizon theorem to $F$ using the preceding lemma.
\end{proof}

This treats network depth as discrete time. For varying layers $F_n(z)=z+g_n(z)$, local constants $L_n$ and defects $d_n$ suggest the sharper nonautonomous expression
\[
 e_n\leq\sum_{j=0}^{n-1}d_j
 \prod_{m=j+1}^{n-1}(1+L_m),
\]
where an empty product is one. Layer-specific analysis can expose stable stages hidden by a single worst-case constant.

\section{Certification algorithms}
\subsection{Geometric propagation}
Evaluate the budget recursively:
\[
 B_0=0,\qquad B_{n+1}=\delta+LB_n.
\]
Then $B_n=\delta\sum_{k=0}^{n-1}L^k$. Producing all values costs $O(N)$ time and $O(N)$ output storage; only $O(1)$ auxiliary storage is needed. The recurrence is numerically preferable to the closed form near $L=1$.

\subsection{Pseudo-orbit audit}
Given $x_0,\ldots,x_N$ and a trusted evaluator, calculate $d_n=\lVert x_{n+1}-f(x_n)\rVert$, set $\widehat\delta=\max d_n$, and verify all invariant-region assumptions. Propagate $\widehat\delta$ with the geometric recurrence. This costs $O(N)$ map evaluations. Directed rounding or interval enclosures are required when the audit is intended as a rigorous upper bound rather than an empirical estimate.

\subsection{Logistic precision planning}
Given $N$ and $\varepsilon$, calculate
\[
 \delta_{\max}=\frac{3\varepsilon}{4^N-1}.
\]
For fixed $\delta$, find the largest integer $N$ satisfying $\delta(4^N-1)\leq3\varepsilon$. Integer powers and direct comparisons avoid threshold errors. This planner certifies the same-initial-condition witness; it does not search for a different long-time shadowing initial state.

\section{Applications and methodology}
A numerical study should distinguish theorem, computational model, and observation. The theorem concerns exact real inequalities. The computational model explains how states are generated and defects bounded. An observed comparison with a high-precision decimal trajectory illustrates scale but is not itself an exact real orbit.

For contracting dynamics $f(x)=Lx$, bounded injected errors demonstrate convergence beneath $\delta/(1-L)$. For logistic dynamics, binary64 and high-precision decimal trajectories can be compared against the factor-four envelope. The envelope will often be conservative because it assumes maximal expansion at every step. For residual systems, bounded layer errors demonstrate the same recurrence across depth.

The results support precision selection, post-execution auditing, and robustness analysis for quantized or approximate residual networks. They also clarify backward-error semantics: first interpret a reported execution as an exact pseudo-orbit with certified local defects; only then apply a dynamical shadowing theorem.

\section{Limitations and future work}
The theory assumes a normed additive state space and a Lipschitz estimate valid over all compared points. In the logistic result, both reported and exact states must lie in $[0,1]$. Exact states remain there by invariance, while reported states require explicit range checks. Uniform $\delta$ and global $L$ may be replaced by local values for sharper bounds.

The interval constant four discards itinerary information. Products of local derivative envelopes $|4-8x|$ may improve finite-horizon budgets away from maximally expanding regions, although behavior near the critical point requires care. Genuine long-time shadowing calls for stable and unstable cone data, angle separation, and an adjusted initial state.

A complementary task is compositional semantics for actual floating-point polynomial programs. Executions avoiding overflow and exceptional values should yield real pseudo-orbits with local bounds expressed through unit roundoff and intermediate magnitudes. For depth-varying residual systems, products of $1+L_n$ suggest that summability or averaged contraction could produce depth-uniform estimates.

\section{Conclusion}
A one-step defect certificate and a Lipschitz bound imply an explicit finite-horizon shadow. The universal radius is $\delta\sum_{k=0}^{n-1}L^k$; contractions give $\delta/(1-L)$; the parameter-four logistic map on $[0,1]$ gives $\delta(4^n-1)/3$; and residual updates use the factor $1+L$. These conclusions justify finite computations under explicit hypotheses while exposing the additional directional and program-level structure required for long-time chaotic shadowing. They also suggest a transparent reporting standard: identify the invariant region, state the local defect and amplification constant, and report the certified horizon and tolerance together. This distinguishes inadequate arithmetic from a coarse dynamical estimate or a genuinely unstable regime. The finite-horizon theory is therefore both a practical certificate and a baseline against which stronger directional shadowing results can be measured.

