from decimal import Decimal as D

def required_delta(epsilon: D, N: int) -> D:
    return D(3)*epsilon/(D(4)**N-D(1))

def certified_horizon(delta: D, epsilon: D) -> int:
    N = 0
    while delta*(D(4)**(N+1)-D(1)) <= D(3)*epsilon:
        N += 1
    return N

print("N_max =", certified_horizon(D("1e-16"), D("1e-10")))
print("delta needed at N=20 =", required_delta(D("1e-10"), 20))

