from decimal import Decimal
def budgets(delta: Decimal, L: Decimal, N: int) -> list[Decimal]:
    out=[Decimal(0)]
    for _ in range(N): out.append(delta+L*out[-1])
    return out

from typing import Callable, Sequence
def audit(f: Callable[[float],float], xs: Sequence[float], L: float) -> tuple[float,list[float]]:
    if not xs or any(not 0.0 <= x <= 1.0 for x in xs): raise ValueError("range failure")
    delta=max((abs(xs[i+1]-f(xs[i])) for i in range(len(xs)-1)),default=0.0)
    b=[0.0]
    for _ in xs[1:]: b.append(delta+L*b[-1])
    return delta,b

from decimal import Decimal
def max_horizon(delta: Decimal, epsilon: Decimal, cap: int=100000) -> int:
    n,p=0,Decimal(1)
    while n<cap and delta*(Decimal(4)*p-1)<=Decimal(3)*epsilon:
        p*=4; n+=1
    return n

